tasks = dict(zip(values('Tasks', 'K420:K425'), values('Tasks', 'L420:L425')))
deps = list(zip(values('Dependencies', 'K38:K43'), values('Dependencies', 'L38:L43')))
succs = {t: [] for t in tasks}
preds = {t: [] for t in tasks}
for s, p in deps:
    succs[p].append(s)
    preds[s].append(p)

# Forward pass (earliest start/finish)
es = {t: 0 for t in tasks}
ef = {t: tasks[t] for t in tasks}
changed = True
while changed:
    changed = False
    for t in tasks:
        if preds[t]:
            m = max(ef[p] for p in preds[t])
            if m > es[t]:
                es[t] = m
                ef[t] = es[t] + tasks[t]
                changed = True

proj_duration = max(ef[t] for t in tasks)

# Backward pass (latest start/finish)
lf = {t: proj_duration for t in tasks}
ls = {t: proj_duration - tasks[t] for t in tasks}
changed = True
while changed:
    changed = False
    for t in tasks:
        if succs[t]:
            m = min(ls[s] for s in succs[t])
            if m < lf[t]:
                lf[t] = m
                ls[t] = lf[t] - tasks[t]
                changed = True

result = ls['Permit'] - es['Permit']

